    if(tab==='revenue')return scenario+panel('Omzet per maand',table(['Periode','Afzet','Bruto omzet'],D.months.map((m,i)=>[esc(m),number(items.reduce((n,p)=>n+p.history[i],0)),money(items.reduce((n,p)=>n+p.history[i]*p.historyPrice,0))]).concat(['Nov 2026','Dec 2026','Jan 2027'].map(m=>[m,number(items.reduce((n,p)=>n+D.forecast(state(),p),0)/3),money(items.reduce((n,p)=>n+D.forecast(state(),p)*p.price,0)/3)]))));
    return scenario+metrics(year.flatMap(f=>[['Omzetforecast '+f.year,money(f.revenue),'Illustratief scenario','chart','green'],['Forecast EBIT '+f.year,money(f.ebit),'Na kosten','money','orange']]))+panel('Voorraadplanning',table(['Artikel','Afzet 3 maanden','Levertijd','Besteladvies'],items.map(p=>[productLink(p),number(D.forecast(state(),p))+' stuks',p.lead+' dagen',hostButton(number(D.need(state(),p))+' stuks bekijken','proposal',p.sku)])));
