  function financePage(){
    const c=client(),t=D.totals(state(),period,channel),ad=D.advertising(state(),period,channel),fixed=(c.fixedMonthly??420)*period,ebit=t.profit-ad-fixed;
    if(page==='bedrijfswaardering'){
      const v=c.valuation,stock=state().products.reduce((n,p)=>n+(D.available(p)+p.external)*p.cost,0),annual=D.annualForecast(state())[0],value=annual.ebit*v.multiple+stock*v.stockPercent/100+v.cash-v.debt;
      return metrics([['Indicatieve waarde',money(value),'Fictieve scenario-uitkomst','money','green'],['Forecast EBIT',money(annual.ebit),'Genormaliseerd voorbeeld','chart'],['Voorraadbijdrage',money(stock*v.stockPercent/100),pct(v.stockPercent)+' van voorraadwaarde','box','orange']])+panel('Eigen waarderingsscenario',form('valuation',field('EBIT-multiple','multiple',v.multiple,'number','min="0" max="10" step="0.1"')+field('Meewegen voorraad (%)','stockPercent',v.stockPercent,'number','min="0" max="100"')+field('Liquide middelen','cash',v.cash,'number','min="0"')+field('Schuldpositie','debt',v.debt,'number','min="0"'),'Scenario doorrekenen','chart'))+details('Berekening van dit voorbeeld',`<p>Forecast EBIT × ${v.multiple} + ${pct(v.stockPercent)} van de voorraadwaarde + liquide middelen − schuldpositie. Dit is een illustratief rekenscenario met fictieve cijfers.</p>`);
    }
    if(page==='bol-afrekening')return panel('Marketplace-tegoeden van je eigen kanalen',D.channels.map(ch=>{const x=D.totals(state(),period,ch.id),reserve=x.revenue*.05,expected=x.revenue-x.fee-reserve;return details(`${brand(ch.id)}<strong>${money(expected)}</strong>${badge('Verwacht','info')}`,table(['Onderdeel','Bedrag'],[['Netto verkoop',money(x.revenue)],['Kanaalkosten','− '+money(x.fee)],['Voorbeeldreserve 5%','− '+money(reserve)],['Verwachte uitbetaling',money(expected)],['Ontvangen in demo',money(c['payout-'+ch.id]||0)]])+button('Voorbeeldontvangst registreren','payout',ch.id,'','money'));}).join(''));
    if(tab==='settings')return panel('Kosten van je eigen exploitatie',form('fixed-costs',field('Overige vaste kosten per maand','fixed',c.fixedMonthly??420,'number','min="0" max="100000"'),'Kosten in scenario opslaan','money'));
    return metrics([['Netto omzet',money(t.revenue),'Na retouren','money','green'],['Brutobijdrage',money(t.profit),'Na directe kosten','chart'],['EBIT',money(ebit),'Na advertenties en vaste kosten','money',ebit<0?'pink':'orange'],['EBIT-marge',pct(t.revenue?ebit/t.revenue*100:0),'Eigen onderneming','chart']])+panel('Exploitatieopbouw',table(['Onderdeel','Periodebedrag'],[['Netto omzet',money(t.revenue)],['Inkoopwaarde','− '+money(t.cost)],['Kanaalkosten','− '+money(t.fee)],['Verzendkosten','− '+money(t.shipping)],['Advertentiekosten','− '+money(ad)],['Overige vaste kosten','− '+money(fixed)],['EBIT',money(ebit)]]))+panel('Bijdrage per kanaal',table(['Kanaal','Netto omzet','Directe kosten','Bijdrage'],D.channels.map(ch=>{const x=D.totals(state(),period,ch.id);return [brand(ch.id),money(x.revenue),money(x.cost+x.fee+x.shipping),money(x.profit)];})));
  }
