    if(page==='ads-engine'&&tab==='articles')return panel('Campagneartikelen',table(['Artikel','Advertentieomzet','Kosten','Actie'],items.map(p=>{const campaigns=state().campaigns.filter(c=>c.sku===p.sku);return [productLink(p),money(campaigns.reduce((n,c)=>n+c.sales,0)),money(campaigns.reduce((n,c)=>n+c.cost,0)),button('Diagnose','diagnosis',p.sku,'','search')];})));
