  function refresh(){
    if(!mounted||rendering)return;rendering=true;
    try{
      const viewKey=page+'|'+tab,openDetails=lastRendered===viewKey?[...node.querySelectorAll('details')].map((el,i)=>el.open?i:-1).filter(i=>i>=0):[];
      CD.ensure(state());const meta=C.pages[page];if(!meta||!renderers[page])throw Error('Onbekend demoscherm: '+page);
      const navGroup=C.groups.find(g=>g.pages.includes(page));root.dataset.fullDemo=page;root.dataset.module=page==='dashboard'?'dashboard':'client';
      root.querySelector('[data-demo-title]').textContent=meta.title;root.querySelector('[data-demo-intro]').textContent=meta.description;
      root.querySelector('.demo-heading .demo-eyebrow').textContent=(navGroup?.label||'Jouw werkplek')+' · Fictieve demo';
      root.querySelectorAll('main>.demo-filters,main>.demo-mobile-menu,main>.demo-channel-strip,main>.demo-home,main>.demo-special,main>.demo-tabs,main>.demo-scenario,main>.demo-metrics,main>.demo-chart,main>.demo-finance-context,main>.demo-table-panel,main>.demo-note').forEach(el=>el.hidden=true);
      root.querySelector('.demo-channel-strip').hidden=true;
      const tabs=meta.tabs||[];if(!tab&&tabs.length)tab=tabs[0].id;
      const nav=tabs.length>1?'<nav class="workspace-tabs" aria-label="Paginaweergaven">'+tabs.map(t=>`<button type="button" data-full-tab="${t.id}" aria-current="${tab===t.id?'page':'false'}">${esc(t.label)}</button>`).join('')+'</nav>':'';
      const filterPages=['omzet','omzet-overzicht','omzet-artikelen','voorraad','magazijn-voorraad','voorraad-incourant','voorraad-overstock','artikeltrends','orders','klanten','inkoop','leveranciers','forecasting','publicaties','bol-afrekening','exploitatie','marketing','ads-engine','retouren','media','verbeteringen'];
      lastExport=[];node.innerHTML=nav+(filterPages.includes(page)?filters():'')+renderers[page]();
      const detailNodes=node.querySelectorAll('details');openDetails.forEach(i=>{if(detailNodes[i])detailNodes[i].open=true;});lastRendered=page+'|'+tab;
      const tools=root.querySelector('.workspace-heading-actions');tools.innerHTML=button('Excel / CSV export','export','','','download')+button('Reset filters','reset-filters','','is-orange','reset');
      tools.hidden=page==='dashboard';
      root.querySelectorAll('[data-full-page]').forEach(b=>{if(b.closest('[data-demo-nav]')){b.setAttribute('aria-current',b.dataset.fullPage===page?'page':'false');if(b.dataset.fullPage===page)b.closest('details').open=true;}});
      const address=new URLSearchParams({page});if(tab)address.set('tab',tab);if(selection&&page==='artikelkaart')address.set('sku',selection);history.replaceState({page,tab},'','?'+address);
    }finally{rendering=false;}
  }
  function navigate(next,nextTab='',push=true){
    if(!C.pages[next]||!renderers[next])return;
    if(push){trail.push({page,tab,selection});history.pushState({page:next,tab:nextTab},'','?'+new URLSearchParams({page:next,...(nextTab?{tab:nextTab}:{})}));}
    if(next==='image-studio')host.setStudio(selection);
    page=next;tab=nextTab&&C.pages[next].tabs.some(t=>t.id===nextTab)?nextTab:(C.pages[next].tabs[0]?.id||'');query='';classification='all';host.close();host.menu(false);refresh();window.scrollTo({top:0,behavior:'instant'});
  }
  function download(name,body,type='text/csv;charset=utf-8'){
    const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
